      (direction === 'next' && nextFocus === value.length) ||
      (direction === 'previous' && nextFocus === -1)
    ) {
      return -1;
    }

    const option = anchorEl.querySelector(`[data-tag-index="${nextFocus}"]`);

    // Same logic as MenuList.js
