      option &&
      (!option.hasAttribute('tabindex') ||
        option.disabled ||
        option.getAttribute('aria-disabled') === 'true')
    ) {
      nextFocus += direction === 'next' ? 1 : -1;
    } else {
      return nextFocus;
    }
  }
}

